          type="number"
          placeholder="Filter by User ID"
          value={userId}
          onChange={(e) => setUserId(e.target.value)}
          data-testid="booking-filter-userId"
        />
      </div>

      <Popover>
        <PopoverTrigger asChild>
          <Button
            variant={'outline'}
            className={cn(
              'w-[200px] justify-start text-left font-normal',
              !startDate && 'text-muted-foreground',
            )}
            data-testid="booking-filter-start-date-trigger"
          >
            <CalendarIcon className="mr-2 h-4 w-4" />
            {startDate ? format(startDate, 'PPP') : <span>Start Date</span>}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-0">
          <Calendar
            mode="single"
            selected={startDate}
            onSelect={setStartDate}
            initialFocus
            data-testid="booking-filter-start-date-calendar"
          />
        </PopoverContent>
      </Popover>

      <Popover>
        <PopoverTrigger asChild>
          <Button
            variant={'outline'}
            className={cn(
              'w-[200px] justify-start text-left font-normal',
              !endDate && 'text-muted-foreground',
            )}
            data-testid="booking-filter-end-date-trigger"
          >
            <CalendarIcon className="mr-2 h-4 w-4" />
            {endDate ? format(endDate, 'PPP') : <span>End Date</span>}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-0">
          <Calendar
            mode="single"
            selected={endDate}
            onSelect={setEndDate}
            initialFocus
            data-testid="booking-filter-end-date-calendar"
          />
        </PopoverContent>
      </Popover>

      <Button onClick={handleClearFilters} variant="outline" data-testid="booking-filter-clear-button">
        Clear Filters
      </Button>
    </div>
  );
};

