          </div>
          <Separator className="my-2" />
          <div className="grid grid-cols-4 gap-4">
            <span className="text-sm font-medium col-span-1">Message:</span>
            <p className="col-span-3 whitespace-pre-wrap">{inquiry.message}</p>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

